queries.carry:Sales \u2013 rolling 28 days by da:
WITH pbi_summary AS (
SELECT d."DAY" AS "DAY", c."Store Region" AS "Store Region" FROM (SELECT DISTINCT dd."CAL_DATE" AS "DAY" FROM (
SELECT * FROM <redacted>."DIM_DATE"
) dd) d CROSS JOIN (SELECT DISTINCT cd0."STORE_REGION" AS "Store Region" FROM (
SELECT * FROM <redacted>."FACT_SALES"
) f LEFT JOIN (
SELECT * FROM <redacted>."DIM_STORE"
) cd0 ON cd0."STORE_KEY" = f."STORE_KEY") c
)
SELECT COUNT(*) AS N FROM (SELECT DISTINCT "DAY" FROM pbi_summary) pbi_n

